const MOCK_NOTIFICATIONS = [
  { id: 'notif-001', message: 'ALERT: Cement Stock Shortage predicted in 4 days (Aug 29)', severity: 'HIGH', createdAt: '2026-08-25 09:00', readStatus: 'UNREAD' },
  { id: 'notif-002', message: 'Ground Floor Slab Concreting ACT-104 DRS exceeds threshold (72.0)', severity: 'CRITICAL', createdAt: '2026-08-25 08:30', readStatus: 'UNREAD' },
  { id: 'notif-003', message: 'NCR-042 Quality honeycombing issue is overdue past 5-day SLA', severity: 'MEDIUM', createdAt: '2026-08-24 17:45', readStatus: 'READ' },
];

// Notifications are currently generated by the frontend because the backend
// does not expose a notifications controller yet. Avoid calling a missing
// endpoint on page load and keep the module usable with its seed alerts.
export const notificationsApi = {
  list: () => Promise.resolve(MOCK_NOTIFICATIONS),
  getById: (id) => Promise.resolve(MOCK_NOTIFICATIONS.find((item) => item.id === id) || MOCK_NOTIFICATIONS[0]),
  create: (payload) => Promise.resolve({ id: `notif-${Date.now()}`, ...payload }),
  update: (id, payload) => Promise.resolve({ id, ...payload }),
};

